edits.find:
CONTENT=$(echo "$TOOL_INPUT" | python3 -c "
import sys, json
try:
    d = json.load(sys.stdin)
    inp = d.get('tool_input', d.get('input', d))
    for key in ['new_string', 'content', 'new_content', 'text']:
        if key in inp:
            print(inp[key][:3000])
            break
except:
    pass
" 2>/dev/null)

[ -z "$CONTENT" ] && exit 0
